mapper.select:
SELECT stock_type, stock_code, SUM(total_shares) AS total_shares FROM (
SELECT stock_type, stock_code, SUM(buying_shares) AS total_shares FROM user_stock_position WHERE position_status = 2 AND buying_shares > 0 GROUP BY stock_type, stock_code UNION ALL
SELECT stock_type, stock_code, SUM(hold_shares) AS total_shares FROM user_follow_up_position WHERE position_status = 0 AND hold_shares > 0 GROUP BY stock_type, stock_code ) combined_data GROUP BY stock_type, stock_code HAVING SUM(total_shares) > 0;
